EXEC dbo.sp_get_hojas_index_paged @Nivel = 0, @Sector = N'', @Sectores = NULL, @Usuario = N'__smoke_test__', @Pendientes = 0, @Numero = NULL, @Cliente = NULL, @Estado = NULL, @SectorFiltro = NULL, @Socio = NULL, @FechaDesde = NULL, @FechaHasta = NULL, @SortField = N'Numero', @SortDirection = N'asc', @PageNumber = 1, @PageSize = 1;
EXEC dbo.sp_get_hojas_by_nivel @Nivel = 0, @Sector = N'', @Sectores = NULL, @Usuario = N'__smoke_test__', @Id = NULL, @Pendientes = 0;
EXEC dbo.sp_get_hojas_by_nivel_base @Nivel = 0, @Sector = N'', @Sectores = NULL, @Usuario = N'__smoke_test__', @Id = NULL, @Pendientes = 0;